{
  "analysis": [
    {
      "layout": "P",
      "strengths": "The most relaxed full-table setting: no measured word splits, single-line headers, and mostly short, natural lines. The generous Behavior column makes the rules easy to read and compare.",
      "faults": "It requires the greatest horizontal travel. The initial viewport shows essentially none of Behavior, so the table’s principal explanatory information is hidden until the reader scrolls.",
      "spatial_logic": "It gives compact codes their minimum useful width, moderate space to names and examples, and nearly half the table to the longest prose."
    },
    {
      "layout": "Q",
      "strengths": "All four columns are visible at once. Among the fitting layouts it is shorter, and its slightly wider Behavior column helps some long rules.",
      "faults": "It splits nine measured words, including the Descriptive Name header and ordinary names, as well as long example terms. Tall, narrow cells disrupt row scanning and produce large empty areas beside wrapped prose.",
      "spatial_logic": "It divides the remaining width fairly evenly after reserving space for Class, favoring Behavior slightly at the expense of names."
    },
    {
      "layout": "R",
      "strengths": "The whole table is visible without horizontal scrolling. Extra name width keeps Mandatory and Combining intact compared with Q.",
      "faults": "The header and several example terms still split inside words. The narrower Behavior column makes the Combining Mark rule eight lines tall, increasing height and weakening row-to-row comparison.",
      "spatial_logic": "It transfers four pixels from Behavior to Descriptive Name while keeping Examples unchanged, trading some prose flow for better name breaks."
    },
    {
      "layout": "S",
      "strengths": "It fits the viewport and has the fewest measured word splits of the fitting candidates. The extra pixel in Examples lets dictionaries remain whole and improves the GL example grouping.",
      "faults": "Six measured word splits remain, including in the header and important example terms. Behavior is still extremely narrow, and the table is as tall as R.",
      "spatial_logic": "It makes a one-pixel adjustment to R in favor of Examples, exploiting a useful wrapping threshold without changing the overall four-column compression."
    },
    {
      "layout": "T",
      "strengths": "It keeps words intact, all headers on one line, and cells to at most three lines while requiring substantially less scrolling than P. Its first three columns make class lookup and example scanning comfortable.",
      "faults": "Behavior begins at the edge of the initial viewport and is effectively hidden. Its narrower prose column increases row heights and creates some spare space in the other columns.",
      "spatial_logic": "It retains P’s roomy identification columns but reduces Examples slightly and cuts Behavior substantially, balancing horizontal travel against vertical expansion."
    },
    {
      "layout": "U",
      "strengths": "It has the least horizontal travel of the scrolling candidates and no measured word splits. The first viewport includes all three identification columns and a visible start of Behavior.",
      "faults": "The Behavior text is cut off at the initial viewport edge, requiring scrolling to read it. The name header wraps, and several names and examples become noticeably taller, especially in the final section.",
      "spatial_logic": "It compresses all three text columns relative to T, accepting more wrapping in exchange for a narrower table."
    }
  ],
  "insights": "The fitting layouts make all columns immediately available, but their width budget cannot accommodate the measured longest units in all three text columns: even their minimum widths total 376 px with Class and padding. Some within-word breaks are therefore unavoidable. Small width changes can nevertheless move breaks across useful thresholds. Scrolling preserves words and improves the reading of rules, but the first viewport must be judged separately: P and T conceal Behavior, while U only hints at it. Row height also matters because a long rule creates blank space across the other columns.",
  "best": ["S", "T"],
  "done": false,
  "designs": [
    {
      "widths": [61, 104, 110, 84],
      "idea": "Fitting candidate: give Descriptive Name and Examples enough width for their measured longest units, concentrating unavoidable splitting in Behavior. This should protect names, identifiers, and examples, but may make rule prose substantially taller; the rendered tradeoff needs checking."
    },
    {
      "widths": [61, 140, 140, 240],
      "idea": "Scrolling candidate: combine T’s single-line header and prose space with narrower identification columns. Behavior starts within the initial viewport, and the smaller total width reduces horizontal travel. Check whether the name header and key examples retain natural breaks at these widths."
    },
    {
      "widths": [61, 130, 140, 220],
      "idea": "Compact scrolling candidate between T and U: give Examples more room than U while keeping Behavior visibly present at first sight and retaining more prose width than U. Compare the resulting header wrap and final-section row heights against the scrolling saved."
    }
  ]
}
